import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> items = new ArrayList<>();
        items.add("apple");
        items.add("banana");
        items.add("cherry");
        for (String item : items) {
            System.out.println(item);
        }
        System.out.println(items.size());
    }
}
